def sample(f,g,a,b,N=1200):
 out=[]
 for i in range(N+1):
  t=a+(b-a)*i/N
  try:out.append((f(t),g(t)))
  except(ValueError,ZeroDivisionError,OverflowError):out.append((math.nan,math.nan))
 return out
