 if yl<=0<=yh:out.append(f'<path d="M45 {Y(0):.2f}H575" stroke="#7e8a9d"/><text x="580" y="{Y(0):.2f}" font-size="12">x</text>')
 if xl<=0<=xh:out.append(f'<path d="M{X(0):.2f} 45V575" stroke="#7e8a9d"/><text x="{X(0)+5:.2f}" y="55" font-size="12">y</text>')
