multi(30,[('a -> III: representative pair',[('x=1+sin(pi t), y=sin(2pi t)',sample(lambda t:1+math.sin(math.pi*t),lambda t:math.sin(2*math.pi*t),0,1))],None),('b -> I: representative pair',[('two vs three oscillations',sample(lambda t:2*math.sin(4*math.pi*t),lambda t:2*math.sin(6*math.pi*t),0,1))],None),('c -> IV: representative pair',[('cubic and semicircle',sample(lambda t:t**3-3*t,lambda t:math.sqrt(4-t*t),-2,2))],None),('d -> II: representative pair',[('minimum and central peak',sample(lambda t:2-3*math.exp(-(t+1)**2/.2),lambda t:-2+4*math.exp(-t*t/.3),-2,2))],None)])
for n,sk,se,ans,k,e,f,g,a,b in [(31,'가로좌표 그래프는 꼭짓점이 원점인 위로 열린 포물선, 세로좌표 그래프는 원점을 지나는 감소 직선이다.','The horizontal-coordinate graph is an upward parabola with vertex at zero; the vertical-coordinate graph is a decreasing line through zero.',r'x=y^2','위 오른쪽에서 원점으로 들어와 아래 오른쪽으로 나간다.','It enters from upper right, reaches the origin, and exits lower right.',lambda t:t*t,lambda t:-t,-1.5,1.5),(32,'가로좌표는 음일부터 일까지 끝값 영·중앙 일인 아래로 열린 포물선이다. 세로좌표는 앞 절반 음수, 뒤 절반 양수인 한 번의 사인형 진동이다.','The horizontal coordinate is a downward parabola on minus one to one with zero endpoints and unit middle value. The vertical coordinate is negative on the first half and positive on the second, completing one sine-like cycle.',r'0\le x\le1,\quad-1\le y\le1','원점에서 오른쪽 아래로 나가 일·영을 지나 왼쪽 위로 원점에 돌아오는 반시계 고리이다.','It leaves the origin down and right, passes (1,0), then returns up and left in a counterclockwise loop.',lambda t:1-t*t,lambda t:math.sin(math.pi*t),-1,1),(33,'가로좌표는 음일·영에서 영·일을 거쳐 일·영으로 가는 삼각형 그래프, 세로좌표는 원점 꼭짓점의 위로 열린 포물선이다.','The horizontal-coordinate graph is a triangular tent from (-1,0) through (0,1) to (1,0); the vertical coordinate is an upward parabola with vertex at zero.',r'y=(1-x)^2,\quad0\le x\le1','영·일부터 일·영까지 곡선을 간 뒤 같은 부분을 되짚는다.','It moves from (0,1) to (1,0), then retraces the same arc.',lambda t:1-abs(t),lambda t:t*t,-1,1)]:
 add(n,sk+' 두 좌표의 매개변수 곡선을 방향과 함께 그려라.',se+' Sketch the parametric curve with orientation.', [('같은 시간의 좌표를 대응시키며 끝점·극값·중간점을 이용한다.','Pair coordinates at equal times, using endpoints, extrema, and the midpoint.'),(k,e)],M(ans)+'; '+k,M(ans)+'; '+e,'도해의 단위 포물선·직선 또는 대표 사인형 보간을 사용한 개형이다.','The sketch uses the unit parabolas and lines, or a representative sine-shaped interpolation shown by the source.')
 svg(n,'Curve inferred from coordinate graphs',[('representative paired graphs',sample(f,g,a,b))])
match=[('a',r'x=t^4-t+1,\ y=t^2','V',lambda t:t**4-t+1,lambda t:t*t,-1.8,1.8),('b',r'x=t^2-2t,\ y=\sqrt t','I',lambda t:t*t-2*t,math.sqrt,0,3),('c',r'x=t^3-2t,\ y=t^2-t','II',lambda t:t**3-2*t,lambda t:t*t-t,-1.8,2),('d',r'x=\cos5t,\ y=\sin2t','VI',lambda t:math.cos(5*t),lambda t:math.sin(2*t),0,2*math.pi),('e',r'x=t+\sin4t,\ y=t^2+\cos3t','IV',lambda t:t+math.sin(4*t),lambda t:t*t+math.cos(3*t),-3,3),('f',r'x=t+\sin2t,\ y=t+\sin3t','III',lambda t:t+math.sin(2*t),lambda t:t+math.sin(3*t),-6,6)]
st34='; '.join('('+letter+') '+M(eq) for letter,eq,*_ in match)
add(34,st34+'을 원문의 그래프 I–VI와 대응시키고 이유를 설명하라.', 'Match '+st34+' to source graphs I–VI and explain.', [('제곱근 식은 위쪽만 그리며 시작점에서 왼쪽으로 휘므로 I이다. 사차 가로좌표와 제곱 세로좌표는 V의 두 위쪽 가지를 준다.','The square-root equation stays above the axis and initially bends left, giving I. Quartic horizontal and squared vertical coordinates give V’s two upper branches.'),('삼차식은 II의 고리, 두 유계 삼각함수는 VI이다. 세로방향 제곱 성장은 IV, 두 좌표의 선형 추세는 III을 준다.','The cubic equation gives II’s loop; the two bounded trigonometric coordinates give VI. Quadratic vertical growth gives IV, and two linear trends give III.')],M(r'\text{a V; b I; c II; d VI; e IV; f III}'),M(r'\text{a V; b I; c II; d VI; e IV; f III}'),'각 매개식을 직접 샘플링한 자체 그림으로 대칭성·유계성·교차를 원문과 대조했다.','Directly sampled plots match source symmetry, boundedness, and intersections.','abcdef')
multi(34,[(f'{letter} -> {label}',[(eq,sample(f,g,a,b))],None) for letter,eq,label,f,g,a,b in match])
add(35,M(r'x=y-2\sin(\pi y)')+'를 그려라.','Graph '+M(r'x=y-2\sin(\pi y)')+'.',[('세로좌표를 매개변수로 둔다.','Use the vertical coordinate as parameter.'),(M(r'x=t-2\sin\pi t,\ y=t')+'을 같은 시간 간격으로 찍는다.',M(r'x=t-2\sin\pi t,\ y=t')+' is sampled at shared parameter values.')],M(r'x=t-2\sin\pi t,\quad y=t,\quad t\in\mathbb R'),M(r'x=t-2\sin\pi t,\quad y=t,\quad t\in\mathbb R'),'가로좌표는 대각선에서 최대 이만큼 옆으로 진동하며 세로좌표는 계속 증가한다.','The horizontal coordinate oscillates at most two units from the diagonal while the vertical coordinate increases.')
