for n,sk,se,ans in [(39,'원점 중심 반지름 오의 원을 시계 방향으로 돌며 한 바퀴에 사 파이 초 걸리는 운동을 나타내라.','Parameterize clockwise motion on a radius-five circle centered at the origin with a revolution taking four pi seconds.',r'x=5\cos(t/2),\quad y=-5\sin(t/2)'),(40,'중심 일·삼, 반지름 일의 원을 반시계 방향으로 돌며 한 바퀴에 삼 초 걸리는 운동을 나타내라.','Parameterize counterclockwise motion on the unit circle centered at (1,3) with a three-second revolution.',r'x=1+\cos(2\pi t/3),\quad y=3+\sin(2\pi t/3)')]:
 add(n,sk,se,[('각속도는 한 바퀴 각도를 주기로 나눈 값이다.','Angular speed is one full-turn angle divided by the period.'),('중심과 반지름을 적용하고 사인항의 부호로 방향을 정한다.','Apply center and radius, using the sine sign for orientation.')],M(ans),M(ans),'주기만큼 시간이 증가하면 같은 점으로 돌아오고 초기 속도는 요청된 방향이다.','One period returns the point, and initial velocity has the requested orientation.')
add(41,M(r'x^2+(y-1)^2=4')+'에서 (a) '+M(r'(2,1)')+'부터 시계 한 바퀴, (b) '+M(r'(2,1)')+'부터 반시계 세 바퀴, (c) '+M(r'(0,3)')+'부터 반시계 반 바퀴를 나타내라.','On '+M(r'x^2+(y-1)^2=4')+', parameterize (a) one clockwise turn from '+M(r'(2,1)')+', (b) three counterclockwise turns from '+M(r'(2,1)')+', and (c) half a counterclockwise turn from '+M(r'(0,3)')+'.', [('중심은 영·일이고 반지름은 이이다. 시작 각도와 매개변수 구간을 바꾼다.','The center is (0,1) and radius two. Adjust starting angle and parameter interval.'),('마지막 경우에는 시작 각도를 파이의 절반으로 둔다.','For the last case use a starting angle of half pi.')],M(r'\text{(a) }(2\cos t,1-2\sin t),\ 0\le t\le2\pi;\quad\text{(b) }(2\cos t,1+2\sin t),\ 0\le t\le6\pi;\quad\text{(c) }(-2\sin t,1+2\cos t),\ 0\le t\le\pi'),M(r'\text{(a) }(2\cos t,1-2\sin t),\ 0\le t\le2\pi;\quad\text{(b) }(2\cos t,1+2\sin t),\ 0\le t\le6\pi;\quad\text{(c) }(-2\sin t,1+2\cos t),\ 0\le t\le\pi'),'초기점과 총 각도 변화가 각각 조건과 일치한다.','Starting points and total angle changes satisfy all cases.','abc')
add(42,'(a) '+M(r'x^2/a^2+y^2/b^2=1')+'을 매개화하고 (b) '+M(r'a=3,\ b=1,2,4,8')+'을 그려 (c) 높이 매개변수의 효과를 설명하라.','(a) Parameterize '+M(r'x^2/a^2+y^2/b^2=1')+', (b) plot '+M(r'a=3,\ b=1,2,4,8')+', and (c) describe the vertical parameter’s effect.', [('단위원의 두 좌표를 각 축 반경만큼 확대한다.','Scale unit-circle coordinates by each semiaxis.'),('가로 폭은 육으로 일정하고 세로 높이는 매개변수의 두 배이다.','Width stays six while height is twice the vertical semiaxis.')],M(r'x=a\cos t,\quad y=b\sin t,\quad0\le t\le2\pi')+'; 높이가 증가하며 두 반경이 같을 때 원이다.',M(r'x=a\cos t,\quad y=b\sin t,\quad0\le t\le2\pi')+'; increasing height gives a circle when semiaxes agree.','삼각항등식으로 원래 타원식이 정확히 성립한다.','The trigonometric identity verifies the ellipse equation.','abc')
